export function beginTrick(kind: PhotovoreTrickKind, x: number, facing: 1 | -1): PhotovoreTrick {
  const anim: TrickAnim =
    kind === "photovore"
    ? "sit"
    : kind === "photon"
      ? "play"
      : kind === "wavelength"
        ? "talk"
        : kind === "glass"
          ? "talk"
          : kind === "lumen"
            ? "sit"
              : "sit";
  return {
    kind: kind,
    phase: kind === "photovore" ? "hold" : "go",
    t: 0,
    x: x,
    lift: 0,
    rot: 0,
    anim: anim,
    facing: facing == null ? 1 : facing,
    fromX: x,
  };
}

function smoothstep(t: number) {
  const x = Math.max(0, Math.min(1, t));
  return x * x * (3 - 2 * x);
}


